const $=id=>document.getElementById(id);
const stages=[
  ["Warm-up","Activate prior knowledge with a quick greeting, movement routine, or visual guessing activity."],
  ["Presentation","Model the target language with clear examples, pictures, gestures, and choral repetition."],
  ["Preparation","Guide learners through a short supported practice before they work more independently."],
  ["Performance","Students complete a meaningful communicative task in pairs or small groups."],
  ["Assessment","Check the learning objective using observation and a brief, visible success criterion."],
  ["Reflection","Students show how they feel about their learning and say or demonstrate one thing they can do."]
];
let currentPlan=null;
function gradeNames(){return Object.keys(MEDUCA_CURRICULUM)}
function fillSelect(select,values){select.innerHTML=values.map(v=>`<option>${v}</option>`).join("")}
function isGrade3General(){return $("grade").value==="3rd Grade"&&$("subject").value!=="English"&&MEDUCA_GRADE3_2026.subjects[$("subject").value]}
function loadThemes(){if(isGrade3General()){const areas=MEDUCA_GRADE3_2026.subjects[$("subject").value],area=areas.find(a=>a.area===$("scenario").value)||areas[0];fillSelect($("theme"),area.topics);return}const data=MEDUCA_CURRICULUM[$("grade").value],row=data.scenarios.find(s=>s[0]===$("scenario").value)||data.scenarios[0];fillSelect($("theme"),[row[1],row[2]])}
function loadGradeCurriculum(){if($("grade").value!=="3rd Grade"&&$("subject").value!=="English")$("subject").value="English";if(isGrade3General()){const areas=MEDUCA_GRADE3_2026.subjects[$("subject").value];$("cefr").value="MEDUCA 2026";fillSelect($("scenario"),areas.map(a=>a.area));loadThemes();$("duration").value="35";return}const data=MEDUCA_CURRICULUM[$("grade").value];$("cefr").value=data.cefr;fillSelect($("scenario"),data.scenarios.map(s=>s[0]));loadThemes();$("duration").value=["Pre-Kinder","Kindergarten"].includes($("grade").value)?"30":"35"}
function loadQuarterCurriculum(){const data=MEDUCA_CURRICULUM[$("quarterGrade").value],names=data.scenarios.map(s=>s[0]);fillSelect($("qScenario1"),names);fillSelect($("qScenario2"),names);$("qScenario2").selectedIndex=1;loadQuarterThemes(1);loadQuarterThemes(2)}
function loadQuarterThemes(which){const data=MEDUCA_CURRICULUM[$("quarterGrade").value],row=data.scenarios.find(s=>s[0]===$("qScenario"+which).value)||data.scenarios[0],offset=which===1?0:2;fillSelect($("qTheme"+(offset+1)),[row[1],row[2]]);fillSelect($("qTheme"+(offset+2)),[row[1],row[2]]);$("qTheme"+(offset+2)).selectedIndex=1}
const activityBank=[
  {title:"Picture Reveal",skill:"Vocabulary",type:"Teams",stage:0,text:"Reveal a picture little by little. Teams predict the word, say it aloud, and use it in the target sentence."},
  {title:"Listen and Point",skill:"Listening",type:"Individual",stage:1,text:"Place picture cards around the board. Say a word or short sentence; learners point to the matching image and repeat."},
  {title:"Information Gap",skill:"Speaking",type:"Pairs",stage:3,text:"Give partners different information. They ask and answer simple questions to complete the missing details without showing their cards."},
  {title:"Role-play Cards",skill:"Speaking",type:"Pairs",stage:3,text:"Students choose simple role cards and perform a short dialogue connected to the scenario using the target vocabulary."},
  {title:"Read, Match, Prove",skill:"Reading",type:"Pairs",stage:2,text:"Students match short statements to pictures, then underline or point to the clue that proves each answer."},
  {title:"Sentence Builder",skill:"Writing",type:"Teams",stage:2,text:"Teams arrange word cards to build correct sentences, read them aloud, and copy one final sentence."},
  {title:"Gallery Walk",skill:"Speaking",type:"Teams",stage:3,text:"Groups create a quick response on paper, walk to observe other groups, and share one useful idea using a sentence frame."},
  {title:"Exit Ticket",skill:"Writing",type:"Individual",stage:5,text:"Each learner completes one short prompt: Today I learned…, I can…, or I need help with…."},
  {title:"Action Check",skill:"Listening",type:"Individual",stage:4,text:"Give three short instructions using the lesson language. Observe whether each learner responds accurately and independently."},
  {title:"Mini Poster",skill:"Vocabulary",type:"Teams",stage:3,text:"Groups create a small visual poster with key words, one model sentence, and a simple illustration related to the theme."}
];

function contextualText(index,data){
  const topic=data.theme;
  const beginner=/beginner|limited/i.test(data.context);
  const visual=beginner?" Use pictures, gestures, modeling, and short repeated phrases.":"";
  const ideas=[
    `Display 3–5 clues related to “${topic}.” Students observe, predict the topic, and repeat key words with actions.${visual}`,
    `Introduce the language needed for “${topic}.” The teacher models meaning, pronunciation, and one useful sentence pattern. Students listen, point, and repeat.${visual}`,
    `Complete a guided matching or sorting task. Check answers together, then rehearse the target sentence with a partner.${visual}`,
    `In pairs, students use the target language to solve a simple real-life challenge connected to “${topic}.” Each learner must speak, point, choose, or demonstrate.${visual}`,
    `Use a teacher checklist: understands the key vocabulary, follows the model, and communicates the main idea. Ask 2–3 students to demonstrate and give brief feedback.`,
    `Students complete an exit signal: “I can do it,” “I need more practice,” or “I need help.” Invite them to share one word or action they learned.`
  ];
  return ideas[index];
}

function distributeMinutes(total){
  const ratios=[.12,.2,.2,.27,.14,.07];
  let mins=ratios.map(r=>Math.max(2,Math.round(total*r)));
  mins[3]+=total-mins.reduce((a,b)=>a+b,0);
  return mins;
}

function generateObjective(){
  const grade=$("grade").value,theme=$("theme").value.trim(),scenario=$("scenario").value.trim(),skill=$("skill").value,evidence=$("evidence").value;
  if(!theme||!scenario){toast("Escriba primero el escenario y el tema.");return ""}
  const action={Speaking:"use key vocabulary and simple sentences",Listening:"identify key words and follow oral instructions",Reading:"identify key information in short supported texts",Writing:"produce short, guided sentences",Mediation:"relay simple information to classmates","Integrated Skills":"understand and use key vocabulary in a meaningful task"}[skill];
  const support=["Pre-Kinder","Kindergarten"].includes(grade)?"through pictures, gestures, repetition, and movement":"through visual support, guided practice, and pair interaction";
  const text=`By the end of the lesson, ${grade} students will be able to ${action} related to “${theme}” within the scenario “${scenario},” ${support}, demonstrating their learning through a ${evidence.toLowerCase()}.`;
  $("objective").value=text;toast("Objetivo redactado con la información de la clase.");return text;
}

function gather(){return {grade:$("grade").value,subject:$("subject").value,planType:$("planType").value,cefr:$("cefr").value,skill:$("skill").value,evidence:$("evidence").value,duration:+$("duration").value,mode:$("mode").value,scenario:$("scenario").value.trim(),theme:$("theme").value.trim(),localPlace:$("localPlace").value.trim(),objective:$("objective").value.trim()||generateObjective(),context:$("context").value.trim(),date:new Date().toLocaleDateString("es-PA")}}

function render(data,body){
  const mins=distributeMinutes(data.duration);
  const stageHtml=stages.map((s,i)=>`<section class="stage"><div class="stage-num">${i+1}</div><div><h3>Stage ${i+1} · ${s[0]}</h3><p contenteditable="true">${body?.[i]||contextualText(i,data)}</p></div><span class="minutes">${mins[i]} min</span></section>`).join("");
  const outcomes={Speaking:"Students interact using modeled words and short sentences.",Listening:"Students recognize vocabulary and respond to simple oral directions.",Reading:"Students locate key information using visual and textual clues.",Writing:"Students create short sentences using a model or word bank.",Mediation:"Students communicate a simple message to a peer.","Integrated Skills":"Students combine receptive and productive skills in a classroom task."};
  $("planDocument").innerHTML=`<p class="editable-note">Haga clic sobre el objetivo o las actividades para editarlos.</p><header class="doc-header"><h2>${data.planType||"Daily Lesson Plan"}</h2><p>Llano Limón Elementary School · Teacher: Mr. Facundo Santo</p></header><div class="meta-grid"><span><b>Level:</b> ${data.grade}</span><span><b>Subject:</b> ${data.subject}</span><span><b>CEFR:</b> ${data.cefr||"A1 Beginner"}</span><span><b>Modality:</b> ${data.mode}</span><span><b>Scenario:</b> ${data.scenario}</span><span><b>Theme:</b> ${data.theme}</span><span><b>Duration:</b> ${data.duration} minutes</span><span><b>Main skill:</b> ${data.skill||"Integrated Skills"}</span></div><div class="objective-box"><b>Learning Objective</b><div contenteditable="true" id="editableObjective">${data.objective}</div></div><div class="curriculum-grid"><div class="curriculum-card"><h3>Learning Outcome</h3><p>${outcomes[data.skill]||outcomes["Integrated Skills"]}</p></div><div class="curriculum-card"><h3>Success Evidence</h3><p>${data.evidence||"Teacher observation"}: the learner uses the target language with visual or teacher support.</p></div><div class="curriculum-card"><h3>21st-Century Skills</h3><p>Communication, collaboration, creativity, and responsible participation.</p></div><div class="curriculum-card"><h3>Resources</h3><p>Board, picture cards or real objects, word bank, notebook or printable task.</p></div></div><h3 class="section-heading">Learning Sequence · Six MEDUCA Stages</h3>${stageHtml}<h3 class="section-heading">Formative Assessment</h3><table class="assessment-table"><thead><tr><th>Criterion</th><th>Achieved</th><th>In progress</th><th>Needs support</th></tr></thead><tbody><tr><td>Recognizes the target vocabulary</td><td>□</td><td>□</td><td>□</td></tr><tr><td>Uses or responds to the target language</td><td>□</td><td>□</td><td>□</td></tr><tr><td>Participates respectfully in the task</td><td>□</td><td>□</td><td>□</td></tr></tbody></table><div class="support-box"><div><b>Differentiation</b>Use modeling, gestures, peer support, fewer choices, and extra repetition for learners who need it. Offer an extension sentence to early finishers.</div><div><b>Teacher Reflection</b>What worked well? What needs reteaching? Which learners need additional support?</div></div>`;
  $("emptyState").classList.add("hidden");$("planDocument").classList.remove("hidden");$("previewStatus").textContent=`${data.grade} · ${data.duration} minutos`;
}

$("objectiveBtn").onclick=generateObjective;
$("plannerForm").addEventListener("submit",e=>{e.preventDefault();currentPlan=gather();if(!currentPlan.objective)return;render(currentPlan);toast("Planificación completa generada. Puede editarla ahora.")});
