function updateCount(){$("savedCount").textContent=saved().length}
function toast(msg){const t=$("toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2200)}

$("saveBtn").onclick=()=>{if(!currentPlan)return toast("Primero genere una planificación.");const plans=saved();const record={...currentPlan,objective:$("editableObjective").innerText.trim(),body:getEditedBody(),id:Date.now()};plans.unshift(record);localStorage.setItem("meducaPlans",JSON.stringify(plans.slice(0,30)));updateCount();toast("Planificación guardada en este dispositivo.")};
$("printBtn").onclick=()=>{if(!currentPlan)return toast("Primero genere una planificación.");window.print()};
$("downloadBtn").onclick=()=>{if(!currentPlan)return toast("Primero genere una planificación.");const html=`<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial;padding:30px;color:#182b3a}h2{text-align:center;color:#12304a}.stage{border-top:1px solid #ccc;padding:10px}h3{color:#1667c7}.meta{background:#f3f7fa;padding:12px}</style></head><body>${$("planDocument").innerHTML}</body></html>`;const blob=new Blob([html],{type:"application/msword"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`Plan_${currentPlan.grade}_${currentPlan.theme.replace(/[^a-z0-9]+/gi,"_")}.doc`;a.click();URL.revokeObjectURL(a.href);toast("Documento descargado.")};

function showSaved(){const plans=saved();$("savedList").innerHTML=plans.length?plans.map(p=>`<div class="saved-item"><div><b>${p.theme}</b><small>${p.grade} · ${p.scenario} · ${p.date}</small></div><button data-id="${p.id}">Abrir</button></div>`).join(""):`<p>Aún no ha guardado planificaciones.</p>`;$("savedDialog").showModal()}
$("savedNav").onclick=showSaved;$("closeDialog").onclick=()=>$("savedDialog").close();$("savedList").onclick=e=>{const id=+e.target.dataset.id;if(!id)return;const p=saved().find(x=>x.id===id);if(p){currentPlan=p;render(p,p.body);$("savedDialog").close();toast("Planificación recuperada.")}};
