function makeRubric(){
  if(!currentPlan){$("rubricOutput").innerHTML='<p>Genere o abra una planificación para contextualizar la rúbrica.</p>';return}
  const total=+$('rubricTotal').value,each=total/5;
  const criteria=["Knowledge and use of target vocabulary","Use of the target language or skill","Completion of the expected evidence","Participation and teamwork","Clarity, effort, and presentation"];
  $("rubricOutput").innerHTML=`<div id="generatedRubric"><div class="rubric-title"><h3>${currentPlan.evidence||"Learning Evidence"} Rubric</h3><p>${currentPlan.grade} · ${currentPlan.theme} · Total: ${total} points</p></div><table class="rubric-table"><thead><tr><th>Criteria</th><th>Excellent<br>${each} pts</th><th>Developing<br>${Math.max(1,each-2)} pts</th><th>Beginning<br>${Math.max(1,each-4)} pt(s)</th><th>Score</th></tr></thead><tbody>${criteria.map(c=>`<tr><td contenteditable="true">${c}</td><td>Consistently and independently</td><td>Usually, with some support</td><td>Rarely, even with support</td><td>____</td></tr>`).join("")}</tbody><tfoot><tr><th colspan="4">TOTAL</th><th>____ / ${total}</th></tr></tfoot></table></div><div class="rubric-actions"><button id="rubricWord">Descargar Word</button><button id="rubricToPlan">Agregar al plan</button></div>`;
  $("rubricWord").onclick=downloadRubric;$("rubricToPlan").onclick=()=>{const copy=$("generatedRubric").cloneNode(true);$("planDocument").append(copy);toast("Rúbrica agregada al documento.")};
}
function downloadRubric(){const html=`<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial;padding:25px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #555;padding:8px}th{background:#12304a;color:white}h3,p{text-align:center}</style></head><body>${$("generatedRubric").innerHTML}</body></html>`;const blob=new Blob([html],{type:"application/msword"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`Rubric_${currentPlan.theme.replace(/[^a-z0-9]+/gi,"_")}.doc`;a.click();URL.revokeObjectURL(a.href)}
$("rubricNav").onclick=()=>{$("rubricDialog").showModal();makeRubric()};$("makeRubric").onclick=makeRubric;
function isoDate(d){return d.toLocaleDateString("en-CA")}
function formatDate(d){return d.toLocaleDateString("en-US",{month:"short",day:"numeric"})}
function quarterData(){return {grade:$("quarterGrade").value,quarter:$("quarterNumber").value,start:$("quarterStart").value,end:$("quarterEnd").value,scenarios:[$("qScenario1").value.trim(),$("qScenario2").value.trim()],themes:[$("qTheme1").value.trim(),$("qTheme2").value.trim(),$("qTheme3").value.trim(),$("qTheme4").value.trim()]}}
function buildQuarter(data){
  const start=new Date(data.start+"T12:00:00"),end=new Date(data.end+"T12:00:00");if(end<start){toast("La fecha final debe ser posterior a la inicial.");return}
  const early=["Pre-Kinder","Kindergarten"].includes(data.grade),weekCount=Math.floor((end-start)/(7*86400000))+1,classes=early?3:4,minutes=early?30:35;
  const rows=[];for(let i=0;i<weekCount;i++){const ws=new Date(start);ws.setDate(start.getDate()+i*7);const we=new Date(ws);we.setDate(ws.getDate()+4);if(we>end)we.setTime(end.getTime());const slot=Math.min(3,Math.floor(i*4/weekCount)),scenario=slot<2?data.scenarios[0]:data.scenarios[1],theme=data.themes[slot];const local=i-Math.floor(slot*weekCount/4);const focus=local<=0?"Introduce vocabulary and model the target language":local===1?"Guided practice through listening, reading, and sentence building":"Communicative performance, evidence, feedback, and reflection";rows.push({week:i+1,dates:`${formatDate(ws)} – ${formatDate(we)}`,scenario,theme,focus,periods:`${classes} periods · ${classes*minutes} min`})}
  $("quarterOutput").innerHTML=`<div id="quarterDocument"><div class="quarter-summary"><div><h3>${data.quarter} · ${data.grade}</h3><p>English · Llano Limón Elementary School · ${isoDate(start)} to ${isoDate(end)}</p></div><div class="quarter-actions"><button id="saveQuarter">Guardar</button><button id="quarterWord">Word</button><button id="quarterPrint">PDF</button></div></div><table class="quarter-table"><thead><tr><th>Week</th><th>Dates</th><th>Scenario</th><th>Theme</th><th>Learning focus / evidence</th><th>Time</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.week}</td><td>${r.dates}</td><td contenteditable="true">${r.scenario}</td><td contenteditable="true">${r.theme}</td><td contenteditable="true">${r.focus}</td><td>${r.periods}</td></tr>`).join("")}</tbody></table></div>`;
  $("saveQuarter").onclick=()=>{localStorage.setItem("meducaQuarterPlan",JSON.stringify({...data,html:$("quarterDocument").innerHTML,date:Date.now()}));toast("Plan trimestral guardado en este dispositivo.")};$("quarterWord").onclick=downloadQuarter;$("quarterPrint").onclick=printQuarter;
}
function quarterHtml(){return `<!doctype html><html><head><meta charset="utf-8"><title>Quarterly Plan</title><style>body{font-family:Arial;padding:24px;color:#182b3a}h3{text-align:center;color:#12304a}p{text-align:center}table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid #657987;padding:7px;vertical-align:top}th{background:#12304a;color:white}.quarter-actions{display:none}</style></head><body>${$("quarterDocument").innerHTML}</body></html>`}
function downloadQuarter(){const blob=new Blob([quarterHtml()],{type:"application/msword"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`Quarterly_Plan_${$("quarterGrade").value.replace(/\s/g,"_")}.doc`;a.click();URL.revokeObjectURL(a.href)}
function printQuarter(){const w=window.open("","_blank");if(!w)return toast("Permita ventanas emergentes para imprimir.");w.document.write(quarterHtml());w.document.close();w.focus();setTimeout(()=>w.print(),250)}
$("quarterNav").onclick=()=>{$("quarterDialog").showModal();const savedQuarter=localStorage.getItem("meducaQuarterPlan");if(savedQuarter&&!$("quarterOutput").innerHTML){const q=JSON.parse(savedQuarter);$("quarterGrade").value=q.grade;loadQuarterCurriculum();$("quarterNumber").value=q.quarter;$("quarterStart").value=q.start;$("quarterEnd").value=q.end;$("qScenario1").value=q.scenarios[0];$("qScenario2").value=q.scenarios[1];loadQuarterThemes(1);loadQuarterThemes(2);q.themes.forEach((t,i)=>$("qTheme"+(i+1)).value=t);buildQuarter(q)}};
$("quarterForm").onsubmit=e=>{e.preventDefault();buildQuarter(quarterData())};
function resourceHeader(title){return `<header class="resource-header"><h2>${title}</h2><p>Llano Limón Elementary School · ${currentPlan.grade} · English · Teacher: Mr. Santo</p></header><div class="student-line"><span>Name: ____________________</span><span>Date: __________</span><span>Score: ______</span></div>`}
function projectPack(){
  const kinder=["Pre-Kinder","Kindergarten"].includes(currentPlan.grade),evidence=currentPlan.evidence||"Mini project";
  return `${resourceHeader(`${currentPlan.theme} · Final Project`)}<section class="resource-section"><h3>My Mission</h3><p contenteditable="true">Create and present a ${evidence.toLowerCase()} that shows what you learned about <b>${currentPlan.theme}</b>. ${kinder?"Use pictures, objects, actions, and words.":"Use the target vocabulary and at least three clear sentences."}</p></section><section class="resource-section"><h3>Steps</h3><div class="project-steps"><div contenteditable="true"><b>Plan</b><br>Choose your ideas and materials.</div><div contenteditable="true"><b>Create</b><br>Make your product neatly with your partner or team.</div><div contenteditable="true"><b>Share</b><br>Present, demonstrate, or explain your work.</div></div></section><section class="resource-section"><h3>Materials</h3><p contenteditable="true">Paper or recycled cardboard, pencil, crayons, picture cards or drawings, scissors, and glue.</p></section><section class="resource-section"><h3>Student Checklist</h3><p>□ I used the lesson vocabulary.&nbsp;&nbsp; □ I completed my part.&nbsp;&nbsp; □ I practiced before sharing.<br>□ I spoke clearly or demonstrated carefully.&nbsp;&nbsp; □ I respected my classmates.</p></section><section class="resource-section"><h3>Teacher Observation</h3><p>Vocabulary: □ Achieved □ In progress □ Needs support &nbsp; Communication: □ Achieved □ In progress □ Needs support</p><p>Comments: ____________________________________________________________________</p></section>`
}
function worksheet(){
  const kinder=["Pre-Kinder","Kindergarten"].includes(currentPlan.grade),high=$("supportLevel").value==="high";
  if(kinder)return `${resourceHeader(`${currentPlan.theme} · Look, Move, and Show`)}<section class="resource-section"><h3>1. Listen and point.</h3><p>Teacher says the words. Point to or draw the correct idea.</p><div class="cut-grid"><div class="cut-card"><b>DRAW</b><div>Picture 1</div></div><div class="cut-card"><b>DRAW</b><div>Picture 2</div></div></div></section><section class="resource-section"><h3>2. Show what you can do.</h3><p>Listen to your teacher. Circle: &nbsp; 😊 I can do it &nbsp;&nbsp; 😐 I need practice &nbsp;&nbsp; 🙋 I need help</p></section>`;
  return `${resourceHeader(`${currentPlan.theme} · Meaningful Practice`)}<section class="resource-section"><h3>1. Build your word bank</h3><p>Write or draw ${high?"four":"six"} useful words from the lesson.</p><div class="word-bank"><span>1. __________</span><span>2. __________</span><span>3. __________</span><span>4. __________</span>${high?"":"<span>5. __________</span><span>6. __________</span>"}</div></section><section class="resource-section"><h3>2. Solve the situation</h3><p contenteditable="true">Imagine you are in the scenario “${currentPlan.scenario}.” Use the words above to prepare a helpful response connected to “${currentPlan.theme}.”</p><div class="answer-lines"></div></section><section class="resource-section"><h3>3. Communicate</h3><p>Share your response with a partner. Your partner checks: □ clear idea &nbsp; □ target words &nbsp; □ complete message</p></section><section class="resource-section"><h3>4. Reflect</h3><p>I can now ________________________________________________________________.</p></section>`
}
function cutCards(){return `${resourceHeader(`${currentPlan.theme} · Cut-and-Use Cards`)}<p>Cut on the dotted lines. Write a target word or draw a picture on each card. Use the cards for matching, speaking, sorting, or team games.</p><div class="cut-grid">${Array.from({length:8},(_,i)=>`<div class="cut-card"><b contenteditable="true">WORD ${i+1}</b><div contenteditable="true">Draw or write an example.</div></div>`).join("")}</div>`}
function generateMaterial(){
  if(!currentPlan){$("materialsOutput").innerHTML='<div class="print-sheet"><p>Genere o abra una planificación primero. El material utilizará sus datos automáticamente.</p></div>';return}
  const type=$("materialType").value,content=type==="project"?projectPack():type==="worksheet"?worksheet():cutCards(),mode=$("printMode").value;
  $("materialsOutput").innerHTML=`<article id="materialDocument" class="print-sheet ${mode}">${content}</article><div class="material-actions"><button id="materialToPlan">Agregar al plan</button><button id="materialWord">Word</button><button id="materialPrint">PDF / Imprimir</button></div>`;
  $("materialToPlan").onclick=()=>{$("planDocument").append($("materialDocument").cloneNode(true));toast("Material agregado a la planificación.")};$("materialWord").onclick=downloadMaterial;$("materialPrint").onclick=printMaterial;
}
function materialHtml(){return `<!doctype html><html><head><meta charset="utf-8"><title>Teaching Material</title><style>body{font-family:Arial;padding:25px;color:#111}.resource-header{text-align:center;border:3px solid #111;padding:10px}.student-line{display:flex;justify-content:space-between;margin:15px 0}.resource-section{border:2px solid #222;padding:12px;margin:12px 0}.project-steps{display:flex;gap:8px}.project-steps div{flex:1;border:1px solid #333;padding:10px}.word-bank{border:2px dashed #333;padding:12px}.word-bank span{display:inline-block;margin:5px}.answer-lines{min-height:120px;background:repeating-linear-gradient(white,white 29px,#777 30px)}.cut-grid{display:grid;grid-template-columns:1fr 1fr}.cut-card{border:2px dashed #333;min-height:130px;padding:12px;text-align:center}</style></head><body>${$("materialDocument").innerHTML}</body></html>`}
function downloadMaterial(){const blob=new Blob([materialHtml()],{type:"application/msword"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`Material_${currentPlan.theme.replace(/[^a-z0-9]+/gi,"_")}.doc`;a.click();URL.revokeObjectURL(a.href)}
function printMaterial(){const w=window.open("","_blank");if(!w)return toast("Permita ventanas emergentes para imprimir.");w.document.write(materialHtml());w.document.close();w.focus();setTimeout(()=>w.print(),250)}
$("materialsNav").onclick=()=>{$("materialsDialog").showModal();generateMaterial()};$("generateMaterial").onclick=generateMaterial;
function renderCurriculum(){const grade=$("curriculumGrade").value,data=MEDUCA_CURRICULUM[grade];$("coverageCefr").textContent=data.cefr;$("curriculumList").innerHTML=data.scenarios.map((s,i)=>`<article class="curriculum-scenario"><div class="number">${i+1}</div><div><h3>${s[0]}</h3><p><b>Theme 1:</b> ${s[1]}</p><p><b>Theme 2:</b> ${s[2]}</p><button data-scenario="${i}">Usar en una planificación</button></div></article>`).join("")}
$("curriculumNav").onclick=()=>{$("curriculumDialog").showModal();renderCurriculum()};$("curriculumGrade").onchange=renderCurriculum;$("curriculumList").onclick=e=>{const i=+e.target.dataset.scenario;if(!e.target.dataset.scenario)return;const grade=$("curriculumGrade").value;$("grade").value=grade;loadGradeCurriculum();$("scenario").selectedIndex=i;loadThemes();$("curriculumDialog").close();toast("Escenario curricular cargado.")};
function renderGrade3Program(){const subject=$("grade3Subject").value,areas=MEDUCA_GRADE3_2026.subjects[subject];$("grade3ProgramList").innerHTML=`<div class="program-subject-title"><span>${areas.length} áreas curriculares</span><h3>${subject}</h3><p>Los contenidos se presentan organizados por área para facilitar la selección docente y la futura creación de planificaciones.</p></div>${areas.map((a,i)=>`<article class="program-area"><div class="program-area-number">${i+1}</div><div><h3>${a.area}</h3><div class="program-topics">${a.topics.map(t=>`<span>${t}</span>`).join("")}</div><button type="button" data-program-topic="${i}">Preparar selección curricular</button></div></article>`).join("")}`}
$("grade3ProgramNav").onclick=()=>{$("grade3ProgramDialog").showModal();renderGrade3Program()};$("grade3Subject").onchange=renderGrade3Program;$("grade3ProgramList").onclick=e=>{if(e.target.dataset.programTopic===undefined)return;$("generalSubject").value=$("grade3Subject").value;loadGeneralAreas();$("generalArea").selectedIndex=+e.target.dataset.programTopic;loadGeneralTopics();$("grade3ProgramDialog").close();$("generalPlannerDialog").showModal();toast("Área y contenidos cargados en el planeamiento general 2026.")};fillSelect($("grade3Subject"),Object.keys(MEDUCA_GRADE3_2026.subjects));
$("grade").onchange=loadGradeCurriculum;$("subject").onchange=loadGradeCurriculum;$("scenario").onchange=loadThemes;$("quarterGrade").onchange=loadQuarterCurriculum;$("qScenario1").onchange=()=>loadQuarterThemes(1);$("qScenario2").onchange=()=>loadQuarterThemes(2);
document.querySelectorAll(".dialog-close").forEach(b=>b.onclick=()=>b.closest("dialog").close());
fillSelect($("curriculumGrade"),gradeNames());loadGradeCurriculum();loadQuarterCurriculum();
updateCount();

// Connected Theme Planner: overview, five skills, daily stages, project and rubric.
const engineSkills=["Listening","Reading","Speaking","Writing","Mediation"];
const engineOutcomes={Listening:"Identifies key words, main ideas, and relevant details in short supported oral texts.",Reading:"Locates explicit information and uses visual and textual clues in short texts.",Speaking:"Interacts using modeled vocabulary, questions, and simple connected sentences.",Writing:"Produces a short organized text using a model, word bank, and revision checklist.",Mediation:"Relays essential information clearly using words, visuals, and simple explanations."};
function loadEngineGrade(){const d=MEDUCA_CURRICULUM[$("engineGrade").value];$("engineCefr").value=d.cefr;fillSelect($("engineScenario"),d.scenarios.map(s=>s[0]));loadEngineTheme();const early=["Pre-Kinder","Kindergarten"].includes($("engineGrade").value);$("engineMinutes").value=early?"30":"35";$("enginePeriods").value=early?"3":"4"}
function loadEngineTheme(){const d=MEDUCA_CURRICULUM[$("engineGrade").value],row=d.scenarios.find(s=>s[0]===$("engineScenario").value)||d.scenarios[0];fillSelect($("engineTheme"),[row[1],row[2]]);loadProjectOptions()}
function engineDate(date,n){const d=new Date(date+"T12:00:00");d.setDate(d.getDate()+n);return d.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"})}
function engineData(){return {grade:$("engineGrade").value,cefr:$("engineCefr").value,scenario:$("engineScenario").value,theme:$("engineTheme").value,localPlace:$("engineLocalPlace").value.trim(),projectType:$("engineProjectType").value,start:$("engineStart").value,periods:+$("enginePeriods").value,minutes:+$("engineMinutes").value,weeks:+$("engineWeeks").value,context:$("engineContext").value,project:$("engineProject").checked,answers:$("engineAnswers").checked,bw:$("engineBw").checked}}
function smartObjective(skill,d){const action={Listening:"identify at least four key details after two listenings",Reading:"locate four explicit details and support each answer with a clue",Speaking:"exchange information using at least three modeled questions and answers",Writing:"draft, revise, and publish four or more connected sentences",Mediation:"relay three essential ideas to a peer using simple language and visual support"}[skill];return `By the end of the lesson, ${d.grade} students will be able to ${action} about “${d.theme},” achieving at least 3 of 4 success criteria.`}
const stageActions={Listening:["Predict words from visual clues.","Listen to a short teacher script twice: first for gist, then for details.","Compare picture or word choices in pairs.","Complete a listen-and-organize challenge and justify one answer.","Check four observable listening criteria and correct misunderstandings.","Complete: Today I heard…, I understood…, I still need…"],Reading:["Use the title and pictures to predict the text.","Model how to find and underline one textual clue.","Match short parts of the text to pictures or headings.","Complete a read-match-prove challenge using evidence.","Answer four comprehension items and show the clues.","Name one reading strategy that helped."],Speaking:["Review language with a picture-and-say team routine.","Model a dialogue, turn-taking, and pronunciation.","Rehearse with sentence frames and change one detail.","Complete an information-gap or role-play in pairs.","Observe clarity, target language, interaction, and completion.","Self-assess: I spoke clearly / I need more practice."],Writing:["Rebuild a model sentence using word cards.","Analyze a model text: beginning, details, and ending.","Plan ideas in a visual organizer and rehearse orally.","Draft, peer-check, revise, and publish.","Check meaning, vocabulary, order, and conventions.","Identify one improvement made after feedback."],Mediation:["Decide which details in two messages are essential.","Model how to simplify and relay a message.","Assign team roles and organize information with icons or notes.","Create and share the final product with a classroom audience.","Use the project rubric and record individual contribution.","Reflect on collaboration and one idea communicated."]};
function engineLesson(skill,index,d){const periods=["Writing","Mediation"].includes(skill)?3:2,total=d.minutes*periods,mins=distributeMinutes(total),support=/beginner|limited/i.test(d.context)?" Use gestures, modeling, repetition, and a visible word bank.":"";return `<section class="engine-lesson" data-lesson="${index}"><h3>Lesson ${index+1} · ${skill}</h3><div class="overview-grid"><div><b>Date</b>${engineDate(d.start,index*3)}</div><div><b>Sequence time</b>${periods} periods · ${total} min</div><div><b>Learning Outcome</b>${engineOutcomes[skill]}</div></div><div class="objective-box"><b>SMART Specific Objective</b><div contenteditable="true">${smartObjective(skill,d)}</div></div><div class="trace-box"><b>Curriculum alignment:</b> ${skill} outcome → observable task → formative evidence.</div>${stages.map((s,i)=>`<div class="lesson-stage"><span>${i+1}</span><div><h4>${s[0]}</h4><p contenteditable="true">${stageActions[skill][i]}${support}</p></div><small>${mins[i]} min</small></div>`).join("")}<div class="support-box"><div><b>Homework</b>${skill==="Mediation"?"Practice the final presentation with the assigned role.":"Review the word bank and prepare one example."}</div><div><b>Teacher comments / observations</b><br><br>________________________________</div></div></section>`}
function renderEngine(d){const rows=engineSkills.map((s,i)=>`<tr><td>${i+1}</td><td>${s}</td><td>${engineDate(d.start,i*3)}</td><td>${["Writing","Mediation"].includes(s)?3:2} periods</td><td>${engineOutcomes[s]}</td></tr>`).join("");$("engineOutput").innerHTML=`<div class="engine-toolbar"><div><b>Paquete generado</b><br><small>${d.grade} · ${d.scenario}</small></div><div class="engine-actions"><button id="engineSave">Guardar</button><button id="engineWord">Word</button><button id="enginePrint">PDF</button></div></div><div id="engineDocument" class="engine-sheet"><div class="engine-title"><h2>THEME PLANNER · OVERVIEW</h2><p>Llano Limón Elementary School · Teacher: Mr. Facundo Santo</p></div><span class="linked-badge">✓ Datos curriculares vinculados</span><div class="overview-grid"><div><b>Grade</b>${d.grade}</div><div><b>CEFR</b>${d.cefr}</div><div><b>Subject</b>English</div><div><b>Scenario</b>${d.scenario}</div><div><b>Theme</b>${d.theme}</div><div><b>Dates</b>${engineDate(d.start,0)} – ${engineDate(d.start,d.weeks*7-3)}</div><div><b>Weekly periods</b>${d.periods}</div><div><b>Minutes per period</b>${d.minutes}</div><div><b>Duration</b>${d.weeks} weeks</div></div><section class="engine-section"><h3>Specific Standards & Learning Outcomes</h3><table class="skills-table"><thead><tr><th>Skill</th><th>Expected outcome</th><th>Observable evidence</th></tr></thead><tbody>${engineSkills.map(s=>`<tr><td><b>${s}</b></td><td contenteditable="true">${engineOutcomes[s]}</td><td>${s==="Listening"?"Listening organizer":s==="Reading"?"Read-match-prove task":s==="Speaking"?"Information-gap performance":s==="Writing"?"Revised short text":"Final product and presentation"}</td></tr>`).join("")}</tbody></table></section><section class="engine-section"><h3>Communicative Competences</h3><div class="overview-grid"><div><b>Linguistic</b>Theme vocabulary, functional sentence patterns, intelligible pronunciation.</div><div><b>Pragmatic</b>Organize information and complete an authentic task.</div><div><b>Sociolinguistic</b>Take turns, use respectful expressions, and adapt the message.</div></div></section><section class="engine-section"><h3>SMART Specific Objectives</h3><table class="skills-table"><tbody>${engineSkills.map(s=>`<tr><th>${s}</th><td contenteditable="true">${smartObjective(s,d)}</td></tr>`).join("")}</tbody></table></section><section class="engine-section"><h3>Materials, Strategies & Differentiation</h3><div class="support-box"><div><b>Materials</b>Board, teacher visuals, real objects or recycled paper, word cards and organizer.</div><div><b>Strategies</b>Modeling, comprehensible input, gradual release, pair work and repeated practice.</div><div><b>Support</b>Fewer choices, pictures, gestures, sentence frames and extra rehearsal.</div><div><b>Extension</b>Additional detail, student-created questions and peer coaching.</div></div></section><section class="engine-section"><h3>Learning Sequence Calendar</h3><table class="skills-table"><thead><tr><th>Lesson</th><th>Skill</th><th>Date</th><th>Time</th><th>Focus</th></tr></thead><tbody>${rows}</tbody></table></section><div class="lesson-tabs">${engineSkills.map((s,i)=>`<button type="button" data-engine-tab="${i}" class="${i===0?"active":""}">${i+1}. ${s}</button>`).join("")}</div>${engineSkills.map((s,i)=>engineLesson(s,i,d)).join("")}${d.project?`<section class="project-card"><h3>21st-Century Project · ${d.theme}</h3><p><b>Driving question:</b> How can we use English to create and share useful classroom information about ${d.theme}?</p><p><b>Final product:</b> A two-page visual classroom publication or presentation produced by editorial teams.</p><p><b>Process:</b> Research → roles → draft → ethical pictures → peer-edit → fact-check → revise → present.</p><table class="skills-table"><thead><tr><th>Criteria</th><th>5</th><th>3</th><th>1</th><th>Score</th></tr></thead><tbody>${["Curriculum content","English communication","Organization and accuracy","Creativity and visual clarity","Collaboration and individual contribution"].map(c=>`<tr><td>${c}</td><td>Complete and independent</td><td>Mostly complete with support</td><td>Limited evidence</td><td>___</td></tr>`).join("")}</tbody><tfoot><tr><th colspan="4">TOTAL</th><th>___ / 25</th></tr></tfoot></table></section>`:""}${d.answers?`<section class="engine-section"><h3>Teacher Script & Answer-Key Guide</h3><p contenteditable="true"><b>Listening script:</b> Prepare a 6–8 sentence message with the theme vocabulary. Read naturally twice.</p><p contenteditable="true"><b>Answer key:</b> Accept answers that identify the correct main idea and details; add reasonable alternatives before printing.</p></section>`:""}<section class="engine-section"><h3>Teacher Reflection</h3><p>What worked well? __________ What needs reteaching? __________ Students needing support: __________</p></section></div>`;$("engineEmpty").classList.add("hidden");$("engineOutput").classList.remove("hidden");bindEngine(d);showEngineLesson(0)}
function showEngineLesson(i){document.querySelectorAll(".engine-lesson").forEach((x,n)=>x.style.display=n===i?"block":"none");document.querySelectorAll("[data-engine-tab]").forEach((x,n)=>x.classList.toggle("active",n===i))}
function engineHtml(){return `<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial;color:#182b3a;padding:25px}table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid #789;padding:7px}th{background:#12304a;color:white}h2,h3{color:#12304a}.overview-grid{display:grid;grid-template-columns:repeat(3,1fr)}.overview-grid div,.project-card,.objective-box{border:1px solid #777;padding:8px}.engine-toolbar,.lesson-tabs,.linked-badge{display:none}.engine-lesson{display:block!important;page-break-before:always}.lesson-stage{border-bottom:1px solid #ccc;padding:8px}.support-box{display:grid;grid-template-columns:1fr 1fr;gap:8px}</style></head><body>${$("engineDocument").innerHTML}</body></html>`}
function bindEngine(d){document.querySelectorAll("[data-engine-tab]").forEach(b=>b.onclick=()=>showEngineLesson(+b.dataset.engineTab));$("engineSave").onclick=()=>{const p=JSON.parse(localStorage.getItem("meducaThemePacks")||"[]");p.unshift({...d,html:$("engineDocument").innerHTML,id:Date.now()});localStorage.setItem("meducaThemePacks",JSON.stringify(p.slice(0,12)));toast("Paquete guardado en este dispositivo.")};$("engineWord").onclick=()=>{const blob=new Blob([engineHtml()],{type:"application/msword"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`MEDUCA_Theme_Planner_${d.grade.replace(/\s/g,"_")}.doc`;a.click();URL.revokeObjectURL(a.href)};$("enginePrint").onclick=()=>{const w=window.open("","_blank");if(!w)return toast("Permita ventanas emergentes para imprimir.");w.document.write(engineHtml());w.document.close();setTimeout(()=>w.print(),300)}}
function topicProfile(d){const q=(d.scenario+" "+d.theme).toLowerCase();let p={type:"classroom information product",mission:`create a useful classroom product about ${d.theme}`,audience:"classmates and families",words:["information","idea","detail","question","answer","share","check","improve"],pattern:"I can explain… / We need… / Our message is…",product:`visual information product about ${d.theme}`,facts:[`what ${d.theme} means`,`three useful details about ${d.theme}`,`one recommendation connected to ${d.theme}`]};if(/news|article|newsletter|reporting|pictures/.test(q))p={type:"classroom newsroom",mission:"publish a trustworthy classroom news story",audience:"students, teachers, and families",words:["headline","article","reporter","editor","source","fact","caption","photograph"],pattern:"I will write… / We need… / Our source says…",product:"two-page classroom newsletter",facts:["event, people, place, and date","two verified facts from a source","a headline and accurate caption"]};else if(/market|shopping|papaya|banana|pineapple|yuca/.test(q))p={type:"market challenge",mission:"plan and perform a realistic market purchase within a budget",audience:"a customer and a vendor",words:["price","total","change","quantity","customer","vendor","need","cost"],pattern:"How much is…? / How many…? / I need…, please.",product:"market dialogue, shopping list, and receipt",facts:["items and quantities needed","price and calculated total","polite request and response"]};else if(/clean|recycl|environment|compost|conservation/.test(q))p={type:"community action campaign",mission:"solve a real cleanliness or environmental problem at school",audience:"the school community",words:["problem","solution","supplies","recycle","reduce","collect","should","will"],pattern:"We should… / I will… / Who will bring…?",product:"action plan and awareness campaign",facts:["the observed problem","responsible action and materials","role, date, and expected result"]};else if(/weather|rain|sunny|umbrella|puddle/.test(q))p={type:"weather service",mission:"prepare a useful weather report and recommendation",audience:"students planning their school day",words:["forecast","temperature","cloudy","rainy","sunny","later","tomorrow","prepare"],pattern:"It will be… / There will be… / You should…",product:"weather bulletin with advice",facts:["current weather evidence","forecast for later or tomorrow","appropriate clothing or safety advice"]};else if(/routine|instruction|cut|poster|sit|pick it up|chores/.test(q))p={type:"instruction design",mission:"create and demonstrate clear instructions for a real task",audience:"a classmate who must complete the task",words:["first","next","then","finally","carefully","before","after","check"],pattern:"First, … / Next, … / Finally, …",product:"illustrated instruction guide and live demonstration",facts:["materials or preparation","steps in logical order","a safety or quality check"]};else if(/food|eat|meal|fruit|vegetable|sancocho/.test(q))p={type:"healthy choice challenge",mission:"recommend and explain a practical meal or food choice",audience:"a family or classmate",words:["meal","ingredient","healthy","portion","need","prefer","because","recommend"],pattern:"We need… / I prefer… because… / It is good for…",product:"meal plan or food recommendation",facts:["foods and quantities","reason for each choice","clear recommendation"]};else if(/library|community|neighborhood|canal|school/.test(q))p={type:"community guide service",mission:"help a visitor find and understand an important place",audience:"a new student or visitor",words:["location","direction","service","important","history","near","across","because"],pattern:"You can find… / Go to… / It is important because…",product:"visitor guide with directions and verified facts",facts:["location and purpose","directions or steps","two accurate and useful facts"]};return p}
function makeRubric(){if(!currentPlan){$("rubricOutput").innerHTML='<p>Genere o abra una planificación para contextualizar la rúbrica.</p>';return}const d={...currentPlan,scenario:currentPlan.scenario||"",theme:currentPlan.theme||""},p=topicProfile(d),total=+$("rubricTotal").value,max=total/5,mid=Math.max(1,Math.round(max*.7)),low=Math.max(1,Math.round(max*.4)),criteria=[[`Required content for the ${p.product}`,`Contains ${p.facts.join("; ")}; information is accurate and useful.`,`Contains most required information; one element needs clarification.`,`Contains one required element or important information is inaccurate.`],[`Target language`, `Uses ${p.pattern} accurately and integrates at least five theme words.`,`Uses the pattern with minor errors and three or four theme words.`,`Uses isolated words or one modeled sentence; errors obscure part of the message.`],[`Communication and audience`,`The ${p.audience} understands the complete message and can respond, decide, or act correctly.`,`The main message is understandable; the audience needs one clarification.`,`Only part of the message is understandable without teacher explanation.`],[`Organization and product conventions`,`The ${p.product} is logically organized, complete, readable/audible, and includes all required features.`,`Organization is generally clear; one feature or revision is incomplete.`,`Several sections are unclear, unfinished, or not arranged for the audience.`],[`Evidence, revision, and individual contribution`,`Sources/details are checked; planning, feedback, revision, and the learner’s assigned contribution are documented.`,`Most process evidence is present; one record or revision is incomplete.`,`Little evidence shows checking, revision, or the learner’s own contribution.`]];$("rubricOutput").innerHTML=`<div id="generatedRubric"><div class="rubric-title"><h3>Analytic Rubric · ${p.product}</h3><p>${d.grade} · ${d.theme} · Authentic mission: ${p.mission} · Total: ${total} points</p></div><table class="rubric-table rubric-deep"><thead><tr><th>Task-specific criterion</th><th>Meets fully<br>${max} pts</th><th>Developing<br>${mid} pts</th><th>Beginning<br>${low} pt(s)</th><th>No evidence<br>0 pts</th><th>Score</th></tr></thead><tbody>${criteria.map(r=>`<tr><td contenteditable="true">${r[0]}</td><td contenteditable="true">${r[1]}</td><td contenteditable="true">${r[2]}</td><td contenteditable="true">${r[3]}</td><td>No observable evidence connected to this criterion.</td><td>___ / ${max}</td></tr>`).join("")}</tbody><tfoot><tr><th colspan="5">TOTAL</th><th>___ / ${total}</th></tr></tfoot></table><p><b>Teacher evidence:</b> language sample/product observed: __________ &nbsp; feedback given: __________ &nbsp; revision completed: □ Yes □ No</p></div><div class="rubric-actions"><button id="rubricWord">Descargar Word</button><button id="rubricToPlan">Agregar al plan</button></div>`;$("rubricWord").onclick=downloadRubric;$("rubricToPlan").onclick=()=>{$("planDocument").append($("generatedRubric").cloneNode(true));toast("Rúbrica analítica agregada al documento.")}}
function meaningfulStages(skill,d){const p=topicProfile(d),w=p.words.slice(0,6).join(", "),f=p.facts;const seq={Listening:[`Display three clues from a ${p.type}. In teams, students predict the message and select four words they expect to hear from this word bank: ${w}. They must explain one prediction using a gesture, drawing, or phrase.`,`Teacher reads the complete authentic message in the Teacher Script. First listening: students choose the speaker, audience, and purpose. Second listening: they record ${f.join("; ")}. Pause only after each complete idea, not after every word.`,`Pairs compare their listening grids. Partner A reports one detail; Partner B points to the matching clue and asks for repetition when needed: “Can you repeat that, please?” The pair agrees on four details before receiving the script.`,`Each pair receives a different missing-information card. They listen to a final short update, decide which detail changes the plan, and give the audience one useful action using ${p.pattern}. Their decision must use evidence from the message.`,`Collect the listening grid and assess: purpose identified, four details recorded, changed information recognized, and action justified. Replay only the section connected to errors; students correct answers in another color.`,`Students finish an audio exit ticket: “The most important detail was ___ because ___.” They mark independently: understood first time / after repetition / still need support.`],Reading:[`Show only the headline or title of the ${p.product}. Students examine it, predict the audience and purpose, and write or draw two facts they expect to find.`,`Reveal a short model text. Think aloud while locating who/what/where/when or the equivalent key details. Underline exact evidence and model why a nearby word is not enough proof.`,`Jigsaw reading: each pair reads a different paragraph. Students highlight one main idea, circle two supporting details, and match one of these key terms to context: ${w}. They prepare a 20-second expert explanation.`,`Re-form groups so each expert shares missing information. The group completes an authentic decision task: choose the most reliable information for the ${p.product}, reject one irrelevant statement, and cite the line that supports every choice.`,`Students answer four evidence-based items: main idea, explicit detail, meaning from context, and author/purpose. Award the point only when the answer and textual clue are both present.`,`Students complete: “I found information by ___.” They compare their original prediction with the text and correct one unsupported idea.`],Speaking:[`Place the words ${w} around the room. Teams receive a real communication need related to “${d.theme}” and move to the three words most useful for solving it. One member explains the choices.`,`Teacher and one student model a complete exchange for a ${p.type}. Class identifies opening, information request, response, follow-up question, and closing. Highlight the functional language: ${p.pattern}.`,`Pairs use role cards with unequal information. They rehearse twice, changing partners after the first attempt. The listener must ask one follow-up question and record the speaker’s key detail; no reading a complete script.`,`Live mission: ${p.mission} for ${p.audience}. Pairs must exchange ${f.join("; ")}. The audience makes a decision from the information, so communication—not memorization—completes the task.`,`Use a speaking record for each learner: message completed, target pattern used twice, understandable pronunciation, follow-up response, and interaction without teacher rescue. Give one specific glow and one next step.`,`Learners replay one difficult line after feedback and record: “My message was clearer when I ___.” Their partner confirms one improvement heard.`],Writing:[`Students sequence four mixed parts of a real ${p.product}. They identify which part attracts attention, gives facts, supports understanding, and closes the message.`,`Analyze a model paragraph connected to “${d.theme}.” Color-code purpose, ${f.join("; ")}, and the language pattern ${p.pattern}. Notice capitalization, punctuation, and one linking word.`,`Students complete a planning organizer for the exact audience: purpose, verified facts, useful vocabulary (${w}), sentence pattern, and visual/caption. A partner checks that every planned idea serves the reader.`,`Students draft the ${p.product}. Required: clear title, at least ${/Pre-Kinder|Kindergarten|1st/.test(d.grade)?2:5} meaningful statements, three target words, the functional pattern, and an audience action or conclusion. Partners use the rubric to suggest one content and one language revision.`,`Students revise before publishing. Teacher verifies content accuracy, message organization, target language, readable conventions, and whether the product helps ${p.audience}. Evidence includes the organizer, first draft, peer note, and final version.`,`Students underline their strongest sentence and annotate one change: “I changed ___ to ___ because ___.”`],Mediation:[`Present a long, mixed set of notes for the ${p.type}. Teams have 90 seconds to decide what ${p.audience} truly needs and remove details that are interesting but not useful.`,`Model mediation: read a source note, select the essential idea, simplify it without changing its meaning, and add a visual or example. Contrast relaying meaning with copying every sentence.`,`Editorial teams assign accountable roles: source checker, language editor, designer, and presenter. Each student transforms one source detail into audience-friendly language and signs the contribution record.`,`Teams assemble and deliver the ${p.product}. It must communicate ${f.join("; ")}, use the target pattern, include an accurate visual/caption, and lead the audience to respond, choose, locate, or act.`,`Apply the analytic project rubric to the actual product and presentation. Verify sources or classroom evidence, score each descriptor, record individual contribution separately, and allow one revision after feedback.`,`Teams answer: What did our audience understand or do? Which source detail did we preserve accurately? What will we improve before publishing or displaying the final version?`]};return seq[skill]}
function performanceOutcome(skill,d){const p=topicProfile(d),n=/Pre-Kinder|Kindergarten/.test(d.grade)?2:/1st|2nd/.test(d.grade)?3:4;return {Listening:`Understands the purpose and records at least ${n} relevant details from an oral ${p.type} message to make a useful decision.`,Reading:`Locates, compares, and cites information from a short ${p.type} text to select reliable details for ${p.audience}.`,Speaking:`Completes a purposeful ${p.type} exchange using ${p.pattern}, a follow-up question, and understandable pronunciation.`,Writing:`Plans, drafts, revises, and publishes a ${p.product} with accurate information, purposeful organization, and theme language.`,Mediation:`Selects, simplifies, and relays essential source information for ${p.audience} without changing its meaning.`}[skill]}
function deepRubric(d){const p=topicProfile(d),facts=p.facts.join("; "),rows=[[`Accuracy and completeness of ${p.type}`,`Includes ${facts}; all information is accurate and useful to ${p.audience}.`,`Includes most required information; one detail needs clarification or support.`,`Includes only one required element or contains an important inaccuracy.`,`Information is missing, copied without understanding, or does not serve the audience.`],[`Target English: ${p.pattern}`,`Uses the functional pattern accurately at least 3 times and integrates 5+ theme words naturally.`,`Uses the pattern at least 2 times and 3–4 theme words; errors do not obscure meaning.`,`Uses isolated words or one modeled sentence; repeated errors sometimes obscure meaning.`,`Does not yet use the target pattern meaningfully, even with the provided support.`],[`Communication with ${p.audience}`,`Message is clear, logically sequenced, audible/readable, and causes the audience to respond or act correctly.`,`Main message is understandable; sequencing or delivery needs minor support.`,`Audience understands only part of the message and needs teacher explanation.`,`Audience cannot identify the purpose or essential message.`],[`Quality of the ${p.product}`,`Title, organization, visual/caption, and final conventions strengthen meaning; evidence of planning and revision is complete.`,`Product is organized and usable; one required feature or revision is incomplete.`,`Product is partially organized; several required features are unclear or unfinished.`,`Product is incomplete or its design prevents the audience from using the information.`],[`Process, sources, and contribution`,`Source details are verified; visuals are used responsibly; assigned role and peer feedback are documented.`,`Sources and contribution are evident; one verification or process record is incomplete.`,`Limited evidence of verification, revision, or individual contribution.`,`No verifiable contribution or responsible use of source information is evident.`]];return `<section class="project-card"><h3>Analytic Performance Rubric · ${p.product}</h3><p><b>Authentic mission:</b> ${p.mission} for ${p.audience}. Score the evidence described—not effort alone. Share this rubric before the task.</p><table class="skills-table rubric-deep"><thead><tr><th>Task-specific criterion</th><th>5 · Exceeds</th><th>4–3 · Meets</th><th>2 · Approaching</th><th>1–0 · Beginning</th><th>Score</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td contenteditable="true">${x}</td>`).join("")}<td>___ / 5</td></tr>`).join("")}</tbody><tfoot><tr><th colspan="5">TOTAL PERFORMANCE SCORE</th><th>___ / 25</th></tr></tfoot></table><p><b>Individual evidence:</b> Role completed: __________ Contribution observed: __________ Revision after feedback: __________</p></section>`}
function engineLesson(skill,index,d){const periods=["Writing","Mediation"].includes(skill)?3:2,total=d.minutes*periods,mins=distributeMinutes(total),seq=meaningfulStages(skill,d);return `<section class="engine-lesson" data-lesson="${index}"><h3>Lesson ${index+1} · ${skill}</h3><div class="overview-grid"><div><b>Date</b>${engineDate(d.start,index*3)}</div><div><b>Sequence time</b>${periods} periods · ${total} min</div><div><b>Performance outcome</b>${performanceOutcome(skill,d)}</div></div><div class="objective-box"><b>SMART Specific Objective</b><div contenteditable="true">${smartObjective(skill,d)}</div></div><div class="trace-box"><b>Alignment:</b> selected MEDUCA scenario/theme → purposeful performance outcome → authentic task → observable product → analytic assessment.</div>${stages.map((s,i)=>`<div class="lesson-stage"><span>${i+1}</span><div><h4>${s[0]} · ${i===0?"Engage & identify the need":i===1?"Model language in context":i===2?"Rehearse with support":i===3?"Complete the authentic mission":i===4?"Collect evidence & give feedback":"Think, revise & transfer"}</h4><p contenteditable="true">${seq[i]}</p></div><small>${mins[i]} min</small></div>`).join("")}<div class="support-box"><div><b>Evidence collected</b>Student organizer/notes, individual language sample, authentic product or decision, assessment record, and reflection/revision.</div><div><b>Differentiation</b>Support: visuals, fewer choices, chunked input, rehearsal and sentence frame. Extension: add evidence, follow-up questions, independent editing or audience adaptation.</div><div><b>Homework with purpose</b>${skill==="Mediation"?"Rehearse the assigned contribution and verify one fact or material needed for the final audience.":"Bring or prepare one real example that will be used in the next connected lesson."}</div><div><b>Teacher comments / observations</b><br><br>________________________________</div></div></section>`}
const originalRenderEngine=renderEngine;
renderEngine=function(d){originalRenderEngine(d);document.querySelectorAll(".engine-lesson").forEach((old,i)=>old.outerHTML=engineLesson(engineSkills[i],i,d));const p=topicProfile(d),standardSection=`<section class="engine-section curriculum-warning"><h3>Curriculum wording and contextual performance</h3><p><b>Official selection:</b> ${d.grade} · ${d.cefr} · ${d.scenario} · ${d.theme}. The performance outcomes below contextualize the selected theme; teachers may edit them to preserve the exact wording from their official curriculum copy.</p><table class="skills-table"><thead><tr><th>Skill</th><th>Contextualized performance outcome</th><th>Required evidence</th></tr></thead><tbody>${engineSkills.map(s=>`<tr><td><b>${s}</b></td><td contenteditable="true">${performanceOutcome(s,d)}</td><td>${s==="Listening"?"Completed listening grid and justified decision":s==="Reading"?"Annotated text and evidence-based response":s==="Speaking"?"Individual interaction record and audience response":s==="Writing"?`Plan, draft, feedback, and final ${p.product}`:`Source transformation, ${p.product}, presentation, and contribution record`}</td></tr>`).join("")}</tbody></table></section>`;const first=$("engineDocument").querySelector(".engine-section");first.outerHTML=standardSection;const project=$("engineDocument").querySelector(".project-card");if(project)project.outerHTML=deepRubric(d);if(d.answers){const guide=[...$("engineDocument").querySelectorAll(".engine-section")].find(x=>x.textContent.includes("Teacher Script"));if(guide)guide.innerHTML=`<h3>Ready-to-Use Teacher Texts & Evidence Guide</h3><p><b>Listening script:</b> Good morning. Our task today is to ${p.mission}. The audience is ${p.audience}. We must include ${p.facts[0]}, ${p.facts[1]}, and ${p.facts[2]}. Use the words ${p.words.slice(0,5).join(", ")}. Check every important detail before sharing it. Each team member must complete a role. At the end, the audience should understand the message and know what to do next.</p><p><b>Model reading:</b> <em>${d.theme}</em> — Our class is preparing a ${p.product}. First, we identified what ${p.audience} needs to know. We checked the important details and removed information that did not support our purpose. Then, we organized the message and used clear English. Before sharing it, another team verified the facts, language, and visual information.</p><p><b>Listening evidence key:</b> purpose—${p.mission}; audience—${p.audience}; required details—${p.facts.join(" / ")}; process—check details and complete roles.</p><p><b>Reading evidence key:</b> main idea—preparing a useful ${p.product}; sequence—identify, check, organize, verify, share; reason for removing information—it did not support the audience or purpose.</p>`}bindEngine(d);showEngineLesson(0)};
const curriculumTopicProfile=topicProfile;
topicProfile=function(d){
  const q=(d.scenario+" "+d.theme).toLowerCase(),place=(d.localPlace||"Our Local Community").trim();
  let p=curriculumTopicProfile(d);
  if(/amazing community|this is my amazing community|school has been here/.test(q))p={type:"community discovery mission",mission:`show why ${place} is a wonderful place to live, learn, and visit`,audience:"students, families, and a first-time visitor",words:["community","beautiful","wonderful","mountain","school","people","history","visit"],pattern:"This is… / You can see… / It is wonderful because…",product:"colorful community discovery guide",facts:[`where ${place} is located`,`three beautiful or important places`,`one local story, tradition, or historical fact`],title:`${place} Is a Wonderful and Beautiful Community`,projectOptions:["Colorful visitor guide and illustrated map","Community heritage mini-museum","Live or recorded community tour","Community pride fair booth"]};
  const catalogs={"classroom newsroom":["Classroom newspaper","Photo news report with captions","School podcast news bulletin","Family information newsletter"],"market challenge":["Market role-play with price tags","Healthy shopping challenge and receipt","Local-products market fair","Budget shopping board game"],"community action campaign":["School action campaign","Recycling station prototype","Environmental awareness mural","Community clean-up proposal"],"weather service":["Class weather studio","Five-day weather bulletin","Weather safety campaign","Seasonal clothing guide"],"instruction design":["Illustrated how-to guide","Live tutorial station","Instruction card game","Safety demonstration video"],"healthy choice challenge":["Healthy Panamanian menu","Family meal planner","Nutrition fair booth","Recipe demonstration"],"community guide service":["Visitor guide and map","Local landmark exhibition","Bilingual walking tour","Community information booth"]};
  p.projectOptions=p.projectOptions||catalogs[p.type]||["Interactive visual exhibition","Collaborative information booklet","Live demonstration for an audience","Classroom campaign with an action plan"];
  p.title=p.title||`${p.product.replace(/^./,c=>c.toUpperCase())}: ${d.theme.replace(/[.!?]+$/g,"")}`;
  return p;
};
function lessonTitle(d){return topicProfile(d).title}
function loadProjectOptions(){if(!$("engineProjectType"))return;const d={grade:$("engineGrade").value,scenario:$("engineScenario").value,theme:$("engineTheme").value,localPlace:$("engineLocalPlace").value.trim()},p=topicProfile(d);fillSelect($("engineProjectType"),p.projectOptions)}
function projectBrief(d,p){const choice=d.projectType||p.projectOptions[0];return `<section class="project-card project-brief"><span class="project-kicker">21ST-CENTURY PROJECT</span><h3>${choice} · ${p.title}</h3><p><b>Driving question:</b> How can we use English to ${p.mission}?</p><p><b>Authentic audience:</b> ${p.audience}.</p><div class="project-choice-grid"><div><b>Final product</b>${choice}</div><div><b>Required content</b>${p.facts.join("; ")}</div><div><b>Language</b>${p.pattern}</div><div><b>Student roles</b>Researcher, language editor, designer, presenter, and fact-checker.</div></div><p><b>Process:</b> Explore → select reliable information → plan → create in color → peer-check → revise → present to the audience.</p></section>`}
contextualText=function(index,d){const p=topicProfile(d),words=p.words.slice(0,6).join(", "),tasks=[`Color Clue Challenge: reveal three colorful visual clues for “${p.title}.” Teams predict the real situation, choose useful words from ${words}, and justify one choice with a gesture or short sentence.`,`Model in Context: present a short message for ${p.audience}. Highlight ${p.pattern}; students connect each expression to a picture, place, object, or action and practice pronunciation with meaning.`,`Rainbow Information Stations: pairs rotate through vocabulary, fact, sentence, and visual stations. They sort or match ${p.facts.join("; ")}, then rehearse one complete message before moving on.`,`Authentic Mission: students ${p.mission}. They create or perform a ${p.product} for ${p.audience}, using the target pattern and at least four theme words. Every learner completes a visible role.`,`Evidence Check: collect the product and one individual language sample. Verify the three required details (${p.facts.join("; ")}), purposeful English, audience clarity, and each learner’s contribution; give one precise improvement.`,`Color Reflection Ticket: green—one thing I can communicate independently; yellow—one part I can do with support; blue—one new idea I will add. Students revise one sentence or detail before finishing.`];return tasks[index]};
const standardRender=render;render=function(data,body){standardRender(data,body);const h=$("planDocument").querySelector(".doc-header h2"),sub=$("planDocument").querySelector(".doc-header p");if(h)h.textContent=lessonTitle(data);if(sub)sub.textContent=`${data.planType||"Daily Lesson Plan"} · Llano Limón Elementary School · Teacher: Mr. Facundo Santo`};
const curriculumRenderEngine=renderEngine;renderEngine=function(d){curriculumRenderEngine(d);const p=topicProfile(d),title=$("engineDocument").querySelector(".engine-title h2"),rubric=$("engineDocument").querySelector(".project-card");if(title)title.textContent=p.title;if(rubric&&d.project)rubric.insertAdjacentHTML("beforebegin",projectBrief(d,p))};
$("engineTheme").onchange=loadProjectOptions;$("engineLocalPlace").oninput=loadProjectOptions;
function closeEngine(){const dialog=$("engineDialog");if(dialog.open)dialog.close();$("engineNav").focus();toast("Regresó a la pantalla principal.")}
$("engineNav").onclick=()=>$("engineDialog").showModal();$("engineBack").onclick=closeEngine;$("engineGrade").onchange=loadEngineGrade;$("engineScenario").onchange=loadEngineTheme;$("engineForm").onsubmit=e=>{e.preventDefault();renderEngine(engineData());toast("Secuencia significativa y rúbrica analítica generadas.")};fillSelect($("engineGrade"),gradeNames());$("engineGrade").value="6th Grade";loadEngineGrade();

// Programa general MEDUCA 2026 · tercer grado
const englishGenerateObjective=generateObjective;
generateObjective=function(){
  if(!isGrade3General())return englishGenerateObjective();
  const subject=$("subject").value,area=$("scenario").value.trim(),topic=$("theme").value.trim(),skill=$("skill").value,evidence=$("evidence").value;
  if(!area||!topic){toast("Seleccione primero el área y el contenido.");return ""}
  const verbs={"Investigación guiada":"investigar, organizar y explicar","Resolución de problemas":"aplicar estrategias y justificar una solución",Comunicación:"comunicar conclusiones con vocabulario propio del área","Expresión creativa":"representar y comunicar una interpretación original","Desempeño práctico":"aplicar el procedimiento con precisión y seguridad","Pensamiento computacional":"descomponer el reto, ordenar pasos y comprobar el resultado"};
  const action=verbs[skill]||"analizar, aplicar y comunicar";
  const text=`Al finalizar la experiencia, el estudiantado de tercer grado será capaz de ${action} el contenido «${topic}» del área «${area}» en ${subject}, mediante una situación vinculada con su entorno, y demostrará el aprendizaje en una evidencia de ${evidence.toLowerCase()} con criterios de exactitud, explicación y aplicación.`;
  $("objective").value=text;toast("Objetivo alineado con el programa MEDUCA 2026.");return text;
};
$("objectiveBtn").onclick=generateObjective;

const englishContextualText=contextualText;
contextualText=function(index,d){
  if(d.subject==="English")return englishContextualText(index,d);
  const place=d.localPlace||"la comunidad cercana",topic=d.theme,area=d.scenario,product=d.evidence||"producto de aprendizaje";
  const subjectTasks={
    "Matemática":["resolver una situación con datos reales del aula o la comunidad","representar el razonamiento con material concreto, dibujo, tabla u operación","comparar dos estrategias y comprobar el resultado"],
    "Ciencias Naturales":["observar un fenómeno, formular una pregunta investigable y anticipar un resultado","registrar observaciones en una tabla o diagrama rotulado","usar la evidencia para aceptar, ajustar o rechazar la explicación inicial"],
    "Español":["interpretar un texto breve y localizar pistas que sostienen una idea","planificar, producir y revisar un mensaje para un destinatario real","justificar una interpretación citando palabras, detalles o recursos del texto"],
    "Ciencias Sociales":["examinar un mapa, imagen, testimonio o fuente del entorno","relacionar el contenido con una decisión ciudadana o comunitaria","comparar perspectivas y sustentar una conclusión con evidencia"],
    "Expresiones Artísticas":["explorar color, ritmo, forma, movimiento o sonido con intención","crear una pieza que comunique una idea sobre el entorno","explicar decisiones creativas y ofrecer retroalimentación respetuosa"],
    "Educación Física":["realizar un reto motor progresivo con reglas y medidas de seguridad","observar técnica, coordinación, esfuerzo y cooperación","ajustar el movimiento a partir de retroalimentación concreta"],
    "Informática":["descomponer una necesidad en pasos claros y ordenados","crear o probar una solución digital sencilla","detectar un error, corregirlo y explicar el uso responsable de la tecnología"],
    "Agricultura":["examinar una necesidad relacionada con suelo, cultivo o ambiente","aplicar un procedimiento práctico con herramientas y normas de seguridad","registrar resultados y proponer una mejora sostenible"],
    "Familia y Desarrollo Comunitario":["analizar una situación auténtica del hogar o la comunidad","tomar una decisión responsable sobre bienestar, convivencia o recursos","crear una recomendación útil y viable para otras personas"],
    "Religión, Moral y Valores":["analizar un dilema cercano desde valores y consecuencias","escuchar otras perspectivas y dialogar con respeto","proponer una acción coherente que fortalezca la convivencia"]
  };
  const moves=subjectTasks[d.subject]||["explorar una situación real","construir una respuesta fundamentada","comunicar y revisar el aprendizaje"];
  const tasks=[
    `Reto inicial con propósito: presente una fotografía, objeto, dato o situación de ${place} relacionada con «${topic}». Sin explicar la respuesta, el estudiantado observa, formula dos preguntas y conecta el reto con una experiencia propia.`,
    `Construcción del concepto: modele cómo ${moves[0]}. Piense en voz alta, destaque el vocabulario de «${area}» y contraste un ejemplo correcto con un error frecuente para que el grupo explique la diferencia.`,
    `Laboratorio guiado: en estaciones de materiales, fuentes y representación, los equipos deben ${moves[1]}. Cada estudiante completa una parte verificable y registra qué evidencia respalda su decisión.`,
    `Desafío auténtico: los equipos aplican «${topic}» para responder una necesidad de ${place}; deben ${moves[2]} y elaborar ${product.toLowerCase()}. El producto tendrá destinatario, propósito y una explicación individual, no solo decoración.`,
    `Evaluación con evidencia: valore exactitud conceptual, aplicación del procedimiento, justificación con evidencia y claridad del ${product.toLowerCase()}. Realice una pregunta de transferencia y permita corregir una parte después de la retroalimentación.`,
    `Reflexión y transferencia: cada estudiante completa «Antes pensaba…; ahora comprendo…; puedo usarlo cuando…». En semáforo terracota–maíz–verde identifica su nivel y escribe una acción concreta para mejorar o aplicar el aprendizaje fuera del aula.`
  ];
  return tasks[index];
};

const grade3Render=render;
render=function(data,body){
  grade3Render(data,body);
  if(data.subject==="English")return;
  const doc=$("planDocument"),title=doc.querySelector(".doc-header h2"),sub=doc.querySelector(".doc-header p"),cards=doc.querySelectorAll(".curriculum-card");
  if(title)title.textContent=`${data.theme}: aprendizaje en acción`;
  if(sub)sub.textContent=`${data.planType} · ${data.subject} · Programa MEDUCA 2026`;
  const cardContent=[
    ["Resultado de aprendizaje",`Aplica el contenido «${data.theme}» del área «${data.scenario}» para interpretar o resolver una situación auténtica y explica cómo obtuvo su respuesta.`],
    ["Evidencia de logro",`${data.evidence}: producto observable acompañado de explicación individual, registro del proceso y una mejora después de la retroalimentación.`],
    ["Competencias del siglo XXI",`${data.skill}; pensamiento crítico, colaboración con responsabilidad individual, comunicación de evidencias y toma de decisiones.`],
    ["Recursos contextualizados",`Objeto, imagen o dato de ${data.localPlace||"la comunidad"}; materiales manipulables o fuentes del área; organizador gráfico; tarjetas de roles; lista de cotejo y materiales para el producto.`]
  ];
  cards.forEach((card,i)=>{card.querySelector("h3").textContent=cardContent[i][0];card.querySelector("p").textContent=cardContent[i][1]});
  const heading=doc.querySelector(".section-heading");if(heading)heading.textContent="Secuencia de aprendizaje · Seis momentos MEDUCA";
  const rows=doc.querySelectorAll(".assessment-table tbody tr");
  const criteria=[`Explica «${data.theme}» con vocabulario y relaciones conceptuales correctas.`,`Aplica una estrategia o procedimiento pertinente y muestra evidencias del proceso.`,`Justifica la respuesta o producto con datos, observaciones, fuentes o ejemplos verificables.`];
  rows.forEach((row,i)=>row.cells[0].textContent=criteria[i]);
};

const generalProfiles={
  "Español":{concept:"conceptos, estructura y propósito comunicativo",procedure:"comprender, producir y revisar mensajes orales, escritos o multimodales",attitude:"escucha, respeto por las ideas y responsabilidad al comunicar",verbs:"interpreta y produce",resource:"texto breve, imágenes secuenciadas, tarjetas de palabras, diccionario y organizador",challenge:"crear un mensaje claro para una audiencia real"},
  "Matemática":{concept:"relaciones, propiedades y lenguaje matemático",procedure:"representar, estimar, calcular, comparar estrategias y comprobar resultados",attitude:"perseverancia, precisión y valoración del error",verbs:"representa y resuelve",resource:"material concreto, recta numérica, tarjetas, tabla de datos y papel cuadriculado",challenge:"resolver una necesidad cotidiana usando más de una representación"},
  "Ciencias Naturales":{concept:"características, relaciones y explicaciones científicas",procedure:"observar, preguntar, predecir, experimentar y registrar evidencias",attitude:"curiosidad, seguridad y cuidado del ambiente",verbs:"investiga y explica",resource:"muestra u objeto seguro, lupa, recipientes, ficha de observación y diagrama",challenge:"explicar un fenómeno cercano a partir de observaciones"},
  "Ciencias Sociales":{concept:"espacio, sociedad, ciudadanía, tiempo e identidad",procedure:"examinar fuentes, ubicar, comparar y proponer acciones",attitude:"participación responsable, identidad y respeto por la diversidad",verbs:"analiza y relaciona",resource:"mapa, fotografía, testimonio, noticia local y línea de tiempo",challenge:"tomar una decisión responsable para la comunidad"},
  "Expresiones Artísticas":{concept:"elementos visuales, corporales, teatrales o musicales",procedure:"explorar técnicas, crear, presentar y apreciar producciones",attitude:"sensibilidad, creatividad y respeto por la expresión propia y ajena",verbs:"explora y crea",resource:"material reutilizable, colores, instrumentos corporales y galería de referentes",challenge:"comunicar una idea del entorno mediante una creación original"},
  "Educación Física":{concept:"movimiento, salud, reglas y seguridad",procedure:"ejecutar, combinar, observar y ajustar habilidades motrices",attitude:"juego limpio, autocuidado y cooperación",verbs:"ejecuta y ajusta",resource:"conos, cuerdas, pelotas, estaciones señalizadas y tarjeta de observación",challenge:"completar un circuito cooperativo con técnica y seguridad"},
  "Informática":{concept:"ciudadanía digital, herramientas y secuencias lógicas",procedure:"organizar, crear, probar, detectar errores y corregir",attitude:"uso responsable, cuidado del equipo y colaboración",verbs:"diseña y comprueba",resource:"computadora compartida o tarjetas de pantalla, bloques de pasos y lista de seguridad",challenge:"crear una solución digital o algoritmo que otra persona pueda seguir"},
  "Agricultura":{concept:"plantas, suelo, producción y sostenibilidad",procedure:"observar, preparar, sembrar, cuidar y registrar cambios",attitude:"responsabilidad, seguridad y valoración del trabajo agrícola",verbs:"aplica y registra",resource:"semillas, suelo, recipientes reutilizados, herramientas seguras y diario de campo",challenge:"mejorar una pequeña situación del huerto o jardín escolar"},
  "Familia y Desarrollo Comunitario":{concept:"bienestar, recursos, alimentación, vivienda y convivencia",procedure:"analizar necesidades, organizar recursos y tomar decisiones",attitude:"autocuidado, corresponsabilidad y respeto",verbs:"evalúa y propone",resource:"casos ilustrados, objetos cotidianos, tabla de decisiones y materiales del hogar",challenge:"proponer una solución viable para el hogar o la comunidad"},
  "Religión, Moral y Valores":{concept:"valores, dignidad, convivencia, creación y servicio",procedure:"dialogar, analizar consecuencias y elegir acciones coherentes",attitude:"empatía, solidaridad, respeto y cuidado",verbs:"reflexiona y actúa",resource:"relato breve, dilema ilustrado, tarjetas de valores y diario de compromisos",challenge:"responder a un dilema cercano con una acción de servicio"}
};
function loadGeneralAreas(){const areas=MEDUCA_GRADE3_2026.subjects[$("generalSubject").value];fillSelect($("generalArea"),areas.map(a=>a.area));loadGeneralTopics()}
function loadGeneralTopics(){const areas=MEDUCA_GRADE3_2026.subjects[$("generalSubject").value],area=areas.find(a=>a.area===$("generalArea").value)||areas[0];fillSelect($("generalTopic"),area.topics)}
function generalData(){return {grade:$("generalGrade").value,subject:$("generalSubject").value,area:$("generalArea").value,topic:$("generalTopic").value,duration:+$("generalDuration").value,grouping:$("generalGrouping").value,context:$("generalContext").value.trim(),competency:$("generalCompetency").value,evidence:$("generalEvidence").value,needs:$("generalNeeds").value.trim()}}
function generalRubric(d,p){return `<table class="skills-table general-rubric"><thead><tr><th>Criterio específico</th><th>4 · Logro destacado</th><th>3 · Logro esperado</th><th>2 · En proceso</th><th>1 · Requiere apoyo</th></tr></thead><tbody><tr><td>Comprensión de «${d.topic}»</td><td>Explica relaciones y aporta un ejemplo nuevo correcto.</td><td>Explica las ideas esenciales con un ejemplo pertinente.</td><td>Reconoce ideas aisladas; necesita preguntas para relacionarlas.</td><td>Aún confunde las ideas esenciales aun con apoyo.</td></tr><tr><td>Proceso propio de ${d.subject}</td><td>${p.verbs} con autonomía, precisión y comprobación.</td><td>${p.verbs} siguiendo el procedimiento y corrige un error.</td><td>Completa parte del proceso con modelado o material de apoyo.</td><td>No completa el proceso o no puede explicar lo realizado.</td></tr><tr><td>Evidencia y justificación</td><td>Usa dos o más evidencias y explica por qué sostienen su respuesta.</td><td>Presenta una evidencia válida y la conecta con su respuesta.</td><td>Presenta evidencia, pero la relación necesita aclaración.</td><td>Responde sin evidencia observable.</td></tr><tr><td>Transferencia y comunicación</td><td>Aplica lo aprendido a una situación nueva y comunica con claridad.</td><td>Aplica lo aprendido al reto planteado y comunica la conclusión.</td><td>Aplica parcialmente con ayuda y comunica información incompleta.</td><td>No logra aplicar el contenido al contexto planteado.</td></tr></tbody></table>`}
function renderGeneralPlan(d){
  const p=generalProfiles[d.subject],context=d.context||"la comunidad cercana",mins=[Math.round(d.duration*.2),Math.round(d.duration*.58)];mins.push(d.duration-mins[0]-mins[1]);
  const objective=`${p.verbs.charAt(0).toUpperCase()+p.verbs.slice(1)} «${d.topic}» para ${p.challenge} en ${context}, utilizando recursos propios de ${d.subject} y justificando el producto con evidencia observable.`;
  $("generalOutput").innerHTML=`<div class="engine-toolbar"><div><b>Planeamiento general generado</b><br><small>${d.subject} · ${d.grade}</small></div><div class="engine-actions"><button id="generalSave">Guardar</button><button id="generalWord">Word</button><button id="generalPrint">PDF</button></div></div><div id="generalDocument" class="engine-sheet general-sheet"><div class="engine-title"><span class="curriculum-seal">PROGRAMA MEDUCA 2026</span><h2>${d.topic}: aprendizaje aplicado en ${context}</h2><p>${d.subject} · ${d.grade} · Área: ${d.area}</p></div><div class="overview-grid"><div><b>Competencia prioritaria</b>${d.competency}</div><div><b>Evidencia principal</b>${d.evidence}</div><div><b>Tiempo y organización</b>${d.duration} minutos · ${d.grouping}</div></div><section class="engine-section"><h3>Alineación curricular</h3><table class="curricular-alignment"><thead><tr><th>Contenido conceptual</th><th>Contenido procedimental</th><th>Contenido actitudinal</th><th>Indicador de logro contextualizado</th><th>Actividad de evaluación</th></tr></thead><tbody><tr><td contenteditable="true">${d.topic}: ${p.concept}.</td><td contenteditable="true">${p.procedure}.</td><td contenteditable="true">${p.attitude}.</td><td contenteditable="true">${p.verbs.charAt(0).toUpperCase()+p.verbs.slice(1)} ${d.topic.toLowerCase()} en una situación de ${context}, registra el proceso y justifica una conclusión.</td><td contenteditable="true">${d.evidence}; explicación individual, registro del proceso y corrección posterior a la retroalimentación.</td></tr></tbody></table></section><div class="objective-box"><b>Objetivo de aprendizaje</b><div contenteditable="true">${objective}</div></div><section class="general-moment start-moment"><div class="moment-number">1</div><div><span>INICIO · ${mins[0]} MIN</span><h3>Situación retadora y saberes previos</h3><p contenteditable="true">Presente una imagen, objeto, dato o caso real de ${context} relacionado con «${d.topic}». El estudiantado realiza la rutina <b>Veo – pienso – me pregunto</b>, comparte una experiencia y formula una pregunta que la clase deberá responder. Registre las ideas iniciales sin confirmar todavía cuál es correcta.</p><div class="moment-product"><b>Evidencia diagnóstica:</b> pregunta investigable, representación inicial o explicación breve.</div></div></section><section class="general-moment develop-moment"><div class="moment-number">2</div><div><span>DESARROLLO · ${mins[1]} MIN</span><h3>Exploración, construcción y aplicación</h3><p contenteditable="true"><b>Explorar:</b> organice estaciones con ${p.resource}. Los equipos observan, manipulan o examinan información y registran patrones, datos o hallazgos.</p><p contenteditable="true"><b>Construir:</b> modele un procedimiento propio de ${d.subject}; contraste una respuesta fundamentada con un error frecuente. Los estudiantes explican la diferencia usando vocabulario del área.</p><p contenteditable="true"><b>Aplicar:</b> proponga el desafío «${p.challenge}». Cada equipo crea ${d.evidence.toLowerCase()}, documenta decisiones y prepara una explicación individual para demostrar que todos aprendieron.</p><div class="moment-product"><b>Evidencia formativa:</b> registro de estación + borrador o procedimiento + retroalimentación entre pares.</div></div></section><section class="general-moment close-moment"><div class="moment-number">3</div><div><span>CIERRE · ${mins[2]} MIN</span><h3>Socialización, metacognición y transferencia</h3><p contenteditable="true">Realice una galería o demostración breve. La audiencia deja una pregunta y una observación basada en evidencia. Cada estudiante responde: «La evidencia que cambió o fortaleció mi idea fue… porque…» y aplica «${d.topic}» a una situación nueva de su hogar, escuela o comunidad.</p><div class="moment-product"><b>Evidencia de cierre:</b> producto mejorado + explicación individual + salida de transferencia.</div></div></section><section class="engine-section"><h3>Evaluación analítica específica</h3>${generalRubric(d,p)}</section><section class="engine-section"><h3>Inclusión, recursos y seguimiento</h3><div class="support-box"><div><b>Apoyos</b>${d.needs}</div><div><b>Recursos</b>${p.resource}.</div><div><b>Extensión</b>Cambiar una condición del reto y pedir una nueva solución argumentada.</div><div><b>Registro docente</b>Hallazgos, dificultades, ajuste y estudiantes que requieren seguimiento: ____________________</div></div></section></div>`;
  $("generalEmpty").classList.add("hidden");$("generalOutput").classList.remove("hidden");bindGeneral(d);toast("Planeamiento general generado con estructura independiente de Inglés.")
}
function generalHtml(){return `<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial;padding:24px;color:#30272a}table{width:100%;border-collapse:collapse;font-size:10px}th,td{border:1px solid #795548;padding:7px;vertical-align:top}th{background:#4a2530;color:white}h2,h3{color:#4a2530}.engine-toolbar{display:none}.general-moment{border:1px solid #aaa;padding:12px;margin:12px 0}.moment-number{font-size:22px;font-weight:bold}.support-box{display:grid;grid-template-columns:1fr 1fr}</style></head><body>${$("generalDocument").innerHTML}</body></html>`}
function bindGeneral(d){$("generalSave").onclick=()=>{const plans=JSON.parse(localStorage.getItem("meducaGeneralPlans")||"[]");plans.unshift({...d,html:$("generalDocument").innerHTML,id:Date.now()});localStorage.setItem("meducaGeneralPlans",JSON.stringify(plans.slice(0,20)));toast("Planeamiento general guardado.")};$("generalWord").onclick=()=>{const blob=new Blob([generalHtml()],{type:"application/msword"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`Planeamiento_${d.subject.replace(/\s/g,"_")}_3_grado.doc`;a.click();URL.revokeObjectURL(a.href)};$("generalPrint").onclick=()=>{const w=window.open("","_blank");if(!w)return toast("Permita ventanas emergentes para imprimir.");w.document.write(generalHtml());w.document.close();setTimeout(()=>w.print(),250)}}
function openTopicGame(){
  let dialog=$("topicGameDialog");if(!dialog){dialog=document.createElement("dialog");dialog.id="topicGameDialog";dialog.className="topic-game-dialog";document.body.append(dialog)}
  const subject=$("bankSubject").value,topic=$("bankTopic").value,icon=(subjectVisuals[subject]||["🎯"])[0],challenges=[`Explica «${topic}» sin repetir las palabras del título.`,`Dibuja o representa un ejemplo de «${topic}» en 30 segundos.`,`Detecta un error que alguien podría cometer en «${topic}» y corrígelo.`,`Conecta «${topic}» con una situación de Llano Limón.`,`Formula una pregunta difícil sobre «${topic}» para el otro equipo.`,`Muestra una evidencia que compruebe una idea sobre «${topic}».`];let index=0,a=0,b=0;
  const paint=()=>{dialog.innerHTML=`<div class="game-board"><button class="game-close" aria-label="Cerrar">×</button><p>${icon} ${subject.toUpperCase()}</p><h2>${topic}</h2><div class="scoreboard"><button data-team="a">EQUIPO SOL <b>${a}</b><small>+ punto</small></button><span>VS</span><button data-team="b">EQUIPO BOSQUE <b>${b}</b><small>+ punto</small></button></div><div class="challenge-card"><small>RETO ${index+1} DE ${challenges.length}</small><strong>${challenges[index]}</strong><button data-next>Nuevo reto ↻</button></div><p class="game-rule">El equipo obtiene el punto solo si explica o muestra evidencia. La clase valida.</p></div>`;dialog.querySelector(".game-close").onclick=()=>dialog.close();dialog.querySelectorAll("[data-team]").forEach(btn=>btn.onclick=()=>{btn.dataset.team==="a"?a++:b++;paint()});dialog.querySelector("[data-next]").onclick=()=>{index=(index+1)%challenges.length;paint()}}
  paint();dialog.showModal();
}
$("generalPlannerNav").onclick=()=>$("generalPlannerDialog").showModal();$("generalBack").onclick=()=>$("generalPlannerDialog").close();$("generalSubject").onchange=loadGeneralAreas;$("generalArea").onchange=loadGeneralTopics;$("generalPlannerForm").onsubmit=e=>{e.preventDefault();renderGeneralPlan(generalData())};fillSelect($("generalSubject"),Object.keys(MEDUCA_GRADE3_2026.subjects));loadGeneralAreas();
